import { test, expect, Page } from '@playwright/test';

test.describe('External Links Open in New Tab', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('about:blank');

    // Create a test page with various external links
    await page.setContent(`
      <!DOCTYPE html>
      <html>
        <head>
          <title>External Links Test Page</title>
        </head>
        <body>
          <h1>Test Page with External Links</h1>

          <nav>
            <a href="https://example.com" target="_blank" rel="noopener noreferrer">Example External Link</a>
            <a href="https://google.com" target="_blank" rel="noopener noreferrer">Google External Link</a>
            <a href="https://github.com" target="_blank" rel="noopener noreferrer">GitHub External Link</a>
          </nav>

          <section>
            <h2>Internal Links</h2>
            <a href="/internal-page">Internal Link</a>
          </section>

          <section>
            <h2>Mixed Content</h2>
            <p>
              Visit <a href="https://www.wikipedia.org" target="_blank" rel="noopener noreferrer">Wikipedia</a> for more info.
            </p>
            <p>
              Check our <a href="/about">About page</a> for details.
            </p>
          </section>

          <footer>
            <a href="https://twitter.com" target="_blank" rel="noopener noreferrer">Follow us on Twitter</a>
          </footer>
        </body>
      </html>
    `);
  });

  test('should open external link in new tab with target="_blank"', async () => {
    // Listen for popup/new page
    const [newPage] = await Promise.all([
      page.context().waitForEvent('page'),
      page.getByRole('link', { name: 'Example External Link' }).click()
    ]);

    // Verify new page opened
    expect(newPage).toBeDefined();

    // Verify the new page has the correct URL
    expect(newPage.url()).toContain('example.com');

    // Verify original page is still on the same URL
    expect(page.url()).toContain('about:blank');

    await newPage.close();
  });

  test('should open multiple external links in separate new tabs', async () => {
    const externalLinks = [
      { name: 'Example External Link', expectedUrl: 'example.com' },
      { name: 'Google External Link', expectedUrl: 'google.com' },
      { name: 'GitHub External Link', expectedUrl: 'github.com' }
    ];

    const newPages: Page[] = [];

    for (const link of externalLinks) {
      const [newPage] = await Promise.all([
        page.context().waitForEvent('page'),
        page.getByRole('link', { name: link.name }).click()
      ]);

      newPages.push(newPage);
      expect(newPage.url()).toContain(link.expectedUrl);
    }

    // Verify original page is still accessible
    expect(page.url()).toContain('about:blank');

    // Verify all new pages are different instances
    expect(newPages.length).toBe(3);
    expect(newPages[0]).not.toBe(newPages[1]);
    expect(newPages[1]).not.toBe(newPages[2]);

    // Clean up
    for (const newPage of newPages) {
      await newPage.close();
    }
  });

  test('should have proper rel attributes for security on external links', async () => {
    const externalLink = page.getByRole('link', { name: 'Example External Link' });

    // Verify target="_blank" attribute
    const target = await externalLink.getAttribute('target');
    expect(target).toBe('_blank');

    // Verify rel="noopener noreferrer" attribute for security
    const rel = await externalLink.getAttribute('rel');
    expect(rel).toContain('noopener');
    expect(rel).toContain('noreferrer');
  });

  test('should distinguish between internal and external links', async () => {
    // Get all links
    const externalLink = page.getByRole('link', { name: 'Wikipedia' });
    const internalLink = page.getByRole('link', { name: 'About page' });

    // Verify external link has target="_blank"
    const externalTarget = await externalLink.getAttribute('target');
    expect(externalTarget).toBe('_blank');

    // Verify internal link does not have target="_blank"
    const internalTarget = await internalLink.getAttribute('target');
    expect(internalTarget).toBeNull();
  });

  test('should open footer external link in new tab', async () => {
    const [newPage] = await Promise.all([
      page.context().waitForEvent('page'),
      page.getByRole('link', { name: 'Follow us on Twitter' }).click()
    ]);

    expect(newPage).toBeDefined();
    expect(newPage.url()).toContain('twitter.com');

    // Verify original page remains unchanged
    expect(page.url()).toContain('about:blank');

    await newPage.close();
  });

  test('should maintain page context when opening external links', async () => {
    const originalUrl = page.url();

    // Open first external link
    const [newPage1] = await Promise.all([
      page.context().waitForEvent('page'),
      page.getByRole('link', { name: 'Example External Link' }).click()
    ]);

    // Verify original page URL hasn't changed
    expect(page.url()).toBe(originalUrl);

    // Open second external link
    const [newPage2] = await Promise.all([
      page.context().waitForEvent('page'),
      page.getByRole('link', { name: 'Google External Link' }).click()
    ]);

    // Verify original page URL still hasn't changed
    expect(page.url()).toBe(originalUrl);

    // Clean up
    await newPage1.close();
    await newPage2.close();
  });
});
